  const int flags = client->SandiumDarkPageFlags(frame->GetLastCommittedURL());
  prefs->sandium_dark_page_flags = flags;
  // Preserve the native baseline and author prefers-color-scheme. Managed OFF
  // is handled by the document style policy, not by mutating shared force-dark.
  return flags != previous_flags;
}
