void StyleAdjuster::ApplySandiumPaintPolicy(ComputedStyleBuilder& builder,
                                    Element& element,
                                    const Element* actual_element,
                                    const ComputedStyle* parent_style) {
  if (builder.SandiumManualColorOverride()) {
    builder.SetColorSchemeForced(false);
    builder.SetSandiumPaletteEnabled(false);
    return;
  }
  const Settings* settings = element.GetDocument().GetSettings();
  if (!settings || settings->GetSandiumDarkPageFlags() < 0 ||
      builder.InForcedColorsMode() || element.GetDocument().Printing()) {
    builder.SetSandiumPaletteEnabled(false);
    return;
  }
  // Preserve excluded regions without allowing a second stock inversion.
  builder.SetColorSchemeForced(false);
  if (!(settings->GetSandiumDarkPageFlags() & 1)) {
    builder.SetSandiumPaletteEnabled(false);
    return;
  }
  const bool document_root = actual_element == element.GetDocument().documentElement() &&
      builder.StyleType() == kPseudoIdNone;
  bool enabled = document_root || (parent_style && parent_style->SandiumPaletteEnabled());
  if ((actual_element && actual_element->IsSVGElement()) ||
      builder.BackgroundInternal().AnyLayerHasImage()) {
    enabled = false;
  }
  builder.SetSandiumPaletteEnabled(enabled);
}

