// Per-draw palette: no process-global policy, image decode or author-style mutation.
SkColor4f SandiumPaletteColor(const SkColor4f& color,
                            DarkModeFilter::ElementRole role) {
  if (color.fA == 0.f || role == DarkModeFilter::ElementRole::kSVG)
    return color;
  if (role == DarkModeFilter::ElementRole::kBorder) {
    const float spread = std::max({color.fR, color.fG, color.fB}) -
        std::min({color.fR, color.fG, color.fB});
    if (spread <= 24.f/255.f)
      return {112.f/255.f, 112.f/255.f, 112.f/255.f, color.fA};
    // Retain validation/error/status hue while lifting visibility on dark surfaces.
    return {(112.f + color.fR * 143.f)/255.f,
            (112.f + color.fG * 143.f)/255.f,
            (112.f + color.fB * 143.f)/255.f, color.fA};
  }
  if (role == DarkModeFilter::ElementRole::kSelection)
    return {23.f/255.f, 58.f/255.f, 91.f/255.f, color.fA};
  const float hi = std::max({color.fR, color.fG, color.fB});
  const float lo = std::min({color.fR, color.fG, color.fB});
  const bool foreground = role == DarkModeFilter::ElementRole::kForeground ||
      role == DarkModeFilter::ElementRole::kListSymbol;
  constexpr float surface = 26.f / 255.f;
  if (foreground) {
    if (lo >= 180.f / 255.f)
      return color;
    if (hi - lo <= 24.f / 255.f)
      return {232.f/255.f, 232.f/255.f, 232.f/255.f, color.fA};
    return {(180.f + color.fR * 75.f)/255.f,
            (180.f + color.fG * 75.f)/255.f,
            (180.f + color.fB * 75.f)/255.f, color.fA};
  }
  if (hi <= surface)
    return color;
  if (hi - lo <= 24.f/255.f)
    return {surface, surface, surface, color.fA};
  return {color.fR * surface, color.fG * surface, color.fB * surface, color.fA};
}

